def squash(s: str) -> str:
    if not s:
        return ""

    def esc(c: str) -> str:
        if c.isdigit() or c == "\\":
            return "\\" + c
        return c

    res = []
    n = len(s)
    i = 0

    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        run_len = j - i
        c = s[i]
        c_esc = esc(c)

        if run_len >= 3:
            res.append(str(run_len))
            res.append(c_esc)
        else:
            res.append(c_esc * run_len)

        i = j

    return "".join(res)
